from typing import List

class Solution:
    def targetIndices(self, nums: List[int], target: int) -> List[int]:
        less = cnt = 0
        for x in nums:
            if x < target:
                less += 1
            elif x == target:
                cnt += 1
        return list(range(less, less + cnt))

