class Solution {
public:
    vector<int> targetIndices(vector<int>& nums, int target) {
        int less = 0, cnt = 0;
        for (int x : nums) {
            if (x < target) ++less;
            else if (x == target) ++cnt;
        }
        vector<int> res;
        for (int i = less; i < less + cnt; ++i) res.push_back(i);
        return res;
    }
};

